css:
/* Base styles shared by all individual balls */
.pb-ball {
  border-radius: 50%;

  /* Your premium grain textures + purple button gradient */
  background-image: radial-gradient(
      circle at bottom center,
      rgba(255, 255, 255, 0.35) 0%,
      rgba(255, 255, 255, 0.15) 20%,
      transparent 60%
    ),
    radial-gradient(rgba(255, 255, 255, 0.12) 0.8px, transparent 0.8px),
    radial-gradient(rgba(255, 255, 255, 0.06) 0.5px, transparent 0.5px),
    linear-gradient(180deg, #a67dff 0%, #7a45ff 45%, #5d24ff 100%);

  background-size:
    100% 100%,
    4px 4px,
    7px 7px,
    100% 100%;
  background-position:
    center,
    0 0,
    2px 2px,
    center;

  /* Internal inset shadow from your design */
  box-shadow: inset 0 2px 10px rgba(255, 255, 255, 0.22);
}

/* The Main Core Ball acts as the coordinate engine and shadow anchor */
.pb-ball-1 {
  position: relative;
  width: 65px;
  height: 65px;
  margin: 100px auto; /* Gives space for the orbiting balls */

  /* Applies the liquid calculation to itself and its children */
  filter: url("#gooey-liquid");
  overflow: visible;

  /* Your exact outer button shadows applied directly to the main element */
  box-shadow:
    0 0 0 6px rgba(125, 71, 255, 0.12),
    0 10px 30px rgba(98, 43, 255, 0.35),
    inset 0 2px 10px rgba(255, 255, 255, 0.22);

  animation: pb-pulse 3s infinite ease-in-out;
}

/* Orbiting droplet 1 */
.pb-ball-2 {
  position: absolute;
  top: calc(50% - 21px); /* Centers relative to parent */
  left: calc(50% - 21px);
  width: 42px;
  height: 42px;
  animation: pb-orbit-left 2.8s infinite ease-in-out;
}

/* Orbiting droplet 2 */
.pb-ball-3 {
  position: absolute;
  top: calc(50% - 16px); /* Centers relative to parent */
  left: calc(50% - 16px);
  width: 32px;
  height: 32px;
  animation: pb-orbit-right 3.5s infinite ease-in-out;
}

/* --- Animations --- */
@keyframes pb-pulse {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.12);
  }
}

@keyframes pb-orbit-left {
  0%,
  100% {
    transform: translateX(-75px) scale(0.85);
  }
  50% {
    transform: translateX(75px) scale(1.05);
  }
}

@keyframes pb-orbit-right {
  0%,
  100% {
    transform: translateY(65px) scale(1.05);
  }
  50% {
    transform: translateY(-65px) scale(0.8);
  }
}
